-- The region of a product is a row of a tree, not a string. alcohol_items.region
-- held '부르고뉴(Bourgogne) > 꼬뜨 드 뉘(Côte de Nuits)' per product; decided
-- 2026-10-26 (format) and 2026-10-29 (tree) that regions live as catalog_terms
-- rows of type region, country rows (ISO code, lower case) at the root and
-- parent_term_key linking each row to the one above, and that a product points
-- at its most specific row through region_key. Depth differs by category: wine
-- country > area > sub-area, whisky country > Scotland > region, sake Japan >
-- prefecture, Korean liquor Korea > province > district. Island names drop '섬'.
-- The card server rebuilds the old region line from the same tree in the
-- dictionary, so saved cards and the regional-style matching are unchanged.

begin;

-- (1) the region tree: a new term type with its own section
alter table public.catalog_terms
  drop constraint catalog_terms_term_type_check,
  add constraint catalog_terms_term_type_check check (
    term_type = any (array['classification', 'style', 'ingredient', 'process', 'maturation',
                           'sensory_descriptor', 'sensory_dimension', 'region'])
  ),
  drop constraint catalog_terms_applicable_sections_check,
  add constraint catalog_terms_applicable_sections_check check (
    cardinality(applicable_sections) > 0
    and public.soolgyul_catalog_text_array_is_valid(applicable_sections, 9, '^[a-z][a-z0-9_]*$')
    and (
      (term_type = 'classification' and applicable_sections <@ array['classification'])
      or (term_type = 'style' and applicable_sections <@ array['style'])
      or (term_type = 'ingredient' and applicable_sections <@ array['ingredient'])
      or (term_type = 'process' and applicable_sections <@ array['production'])
      or (term_type = 'maturation' and applicable_sections <@ array['maturation'])
      or (term_type = 'region' and applicable_sections <@ array['region'])
      or (term_type in ('sensory_descriptor', 'sensory_dimension')
          and applicable_sections <@ array['aroma', 'palate', 'finish', 'texture'])
    )
  );

insert into public.catalog_terms (
  term_type, term_key, label_ko, label_en, synonyms, parent_term_key,
  applicable_sections, metadata, taxonomy_version, sort_order, is_active
)
